(1, 1, 'بنر رقم ١', 'Banner #1', 'هناك حقيقة مثبتة منذ زمن طويل وهي أن المحتوى المقروء لصفحة ما سيلهي القارئ عن التركيز على الشكل الخارجي للنص. هناك حقيقة  وهي أن المحتوى المقروء لصفحة ما سيلهي القارئ.', 'It is a long established fact that a reader will be distracted by the readable content of a page. It is a long established fact that a reader will be distracted.', NULL, 'noimg.png', 'noimg.png', NULL, NULL, '#', NULL, NULL, NULL, 1, 0, 1, 1, NULL, '2026-09-26 21:56:03', '2026-09-26 21:56:03'),
(2, 1, 'بنر رقم ٢', 'Banner #2', 'هناك حقيقة مثبتة منذ زمن طويل وهي أن المحتوى المقروء لصفحة ما سيلهي القارئ عن التركيز على الشكل الخارجي للنص. هناك حقيقة  وهي أن المحتوى المقروء لصفحة ما سيلهي القارئ.', 'It is a long established fact that a reader will be distracted by the readable content of a page. It is a long established fact that a reader will be distracted.', NULL, 'noimg.png', 'noimg.png', NULL, NULL, '#', NULL, NULL, NULL, 1, 0, 2, 1, NULL, '2026-09-26 21:56:03', '2026-09-26 21:56:03'),
(3, 2, 'تصميم ريسبونسف', 'Responsive Design', 'هناك حقيقة مثبتة منذ زمن طويل وهي أن المحتوى المقروء لصفحة ما سيلهي القارئ عن التركيز على الشكل الخارجي للنص.', 'It is a long established fact that a reader will be distracted by the readable content of a page.', NULL, '', '', NULL, NULL, '#', NULL, NULL, 'fa fa-object-group', 1, 0, 1, 1, NULL, '2026-09-26 21:56:03', '2026-09-26 21:56:03'),
(4, 2, ' احدث التقنيات', 'HTML5 & CSS3', 'هناك حقيقة مثبتة منذ زمن طويل وهي أن المحتوى المقروء لصفحة ما سيلهي القارئ عن التركيز على الشكل الخارجي للنص.', 'It is a long established fact that a reader will be distracted by the readable content of a page.', NULL, '', '', NULL, NULL, '#', NULL, NULL, 'fab fa-html5', 1, 0, 2, 1, NULL, '2026-09-26 21:56:03', '2026-09-26 21:56:03'),
(5, 2, 'باستخدام بوتستراب', 'Bootstrap Used', 'هناك حقيقة مثبتة منذ زمن طويل وهي أن المحتوى المقروء لصفحة ما سيلهي القارئ عن التركيز على الشكل الخارجي للنص.', 'It is a long established fact that a reader will be distracted by the readable content of a page.', NULL, '', '', NULL, NULL, '#', NULL, NULL, 'fa fa-code', 1, 0, 3, 1, NULL, '2026-09-26 21:56:03', '2026-09-26 21:56:03'),
(6, 2, 'تصميم كلاسيكي', 'Classic Design', 'هناك حقيقة مثبتة منذ زمن طويل وهي أن المحتوى المقروء لصفحة ما سيلهي القارئ عن التركيز على الشكل الخارجي للنص.', 'It is a long established fact that a reader will be distracted by the readable content of a page.', NULL, '', '', NULL, NULL, '#', NULL, NULL, 'fa fa-laptop', 1, 0, 4, 1, NULL, '2026-09-26 21:56:03', '2026-09-26 21:56:03');

