(12, 8, 5, 'Testimonials', 3, '{\"title_en\":\"Testimonials\",\"desc_en\":\"We are proud of our customers testimonials, which reflect their satisfaction with our services.\",\"bg_en\":null,\"title_ar\":\"أراء العملاء\",\"desc_ar\":\"نحن فخورون بشهادات عملائنا، والتي تعكس رضاهم عن خدماتنا المميزة.\",\"bg_ar\":null,\"title_ch\":\"客户评价\",\"desc_ch\":\"我们为客户的好评感到自豪，这反映了他们对我们的服务的满意度。\",\"bg_ch\":null,\"title_hi\":\"प्रशंसापत्र\",\"desc_hi\":\"हमें अपने ग्राहकों के प्रशंसापत्र पर गर्व है, जो हमारी सेवाओं से उनकी संतुष्टि को दर्शाते हैं।\",\"bg_hi\":null,\"title_es\":\"Testimonios\",\"desc_es\":\"Estamos orgullosos de los testimonios de nuestros clientes, que reflejan su satisfacción con nuestros servicios.\",\"bg_es\":null,\"title_ru\":\"Отзывы\",\"desc_ru\":\"Мы гордимся отзывами наших клиентов, которые отражают их удовлетворенность нашими услугами.\",\"bg_ru\":null,\"title_pt\":\"Testemunhos\",\"desc_pt\":\"Orgulhamo-nos dos testemunhos dos nossos clientes, que refletem a sua satisfação com os nossos serviços.\",\"bg_pt\":null,\"title_fr\":\"Témoignages\",\"desc_fr\":\"Nous sommes fiers des témoignages de nos clients, qui reflètent leur satisfaction quant à nos services.\",\"bg_fr\":null,\"title_de\":\"Kundenstimmen\",\"desc_de\":\"Wir sind stolz auf die Kundenstimmen, die ihre Zufriedenheit mit unseren Dienstleistungen widerspiegeln.\",\"bg_de\":null,\"title_th\":\"ข้อความรับรอง\",\"desc_th\":\"เราภูมิใจกับคำรับรองของลูกค้าซึ่งสะท้อนถึงความพึงพอใจของพวกเขาต่อบริการของเรา\",\"bg_th\":null,\"title_br\":\"Depoimentos\",\"desc_br\":\"Temos orgulho dos depoimentos de nossos clientes, que refletem sua satisfação com nossos serviços.\",\"bg_br\":null,\"module_id\":\"11\",\"category_ids\":null,\"records_count\":\"6\",\"records_order\":\"1\",\"view_style\":\"Testimonials\"}', 1, 1, 0, 0, 0, NULL, NULL, 1, 1, NULL, '2026-09-26 21:56:03', '2026-09-26 21:56:03'),
